'use strict';
let characterWorkspaceTab='animate',voicePreviewTimer=null;
const selectionNotice=document.createElement('section');selectionNotice.id='selectionNotice';selectionNotice.className='selection-notice';selectionNotice.setAttribute('aria-live','polite');selectionNotice.innerHTML='<strong id="selectionKind"></strong><span id="selectionExplanation"></span><button id="selectionUnlock" hidden>Unlock editing</button><button id="selectionChoose" hidden>Choose character</button>';
$('selectionTitle').after(selectionNotice);
const characterWorkspace=document.createElement('nav');characterWorkspace.id='characterWorkspace';characterWorkspace.className='character-workspace';characterWorkspace.setAttribute('aria-label','Character workspace');characterWorkspace.innerHTML='<button data-character-section="add">Add</button><button data-character-section="appearance">Appearance</button><button data-character-section="animate">Animate</button><button data-character-section="voice">Voice</button>';
selectionNotice.after(characterWorkspace);
function editableCharacter(candidate=object()){if(!isAnimatedCharacter(candidate)){const choices=current().objects.filter(isAnimatedCharacter);if(choices.length===1){candidate=choices[0];selectLayers([candidate.id])}else{toast(choices.length?'Choose a character on the canvas or in the character selector.':'Add a character from Cast before animating.');if(choices.length)$('selectionChoose').click();else tab('cast');return null}}if(candidate.locked){selectLayers([candidate.id]);render();toast(candidate.name+' has an editing lock. Choose Unlock editing in the inspector.');return null}return candidate}
const walkBeforeSelection=startWalkClick;startWalkClick=function(o,...args){o=editableCharacter(o);if(o)return walkBeforeSelection(o,...args)};
const addActionBeforeSelection=addActionBlock;addActionBlock=function(o,...args){o=editableCharacter(o);if(o)return addActionBeforeSelection(o,...args)};
const bodyBeforeSelection=openBodyAnimation;openBodyAnimation=function(o,...args){o=editableCharacter(o);if(o)return bodyBeforeSelection(o,...args)};
const motionBeforeSelection=openMotionLibrary;openMotionLibrary=function(o,...args){o=editableCharacter(o);if(o)return motionBeforeSelection(o,...args)};
const mouthBeforeSelection=openMouthCueEditor;openMouthCueEditor=function(o,...args){o=editableCharacter(o);if(o)return mouthBeforeSelection(o,...args)};
document.body.insertAdjacentHTML('beforeend','<dialog id="chooseCharacterDialog"><div class="tool-heading"><h2>Choose a character</h2><button id="closeChooseCharacter">Close</button></div><div id="chooseCharacterList" class="ease-card-list"></div></dialog>');
$('selectionChoose').onclick=()=>{const list=$('chooseCharacterList');list.replaceChildren();for(const o of current().objects.filter(isAnimatedCharacter)){const b=storyButton(o.name+(o.locked?' · editing locked':''),()=>{selectLayers([o.id]);$('chooseCharacterDialog').close();render()});b.dataset.characterId=o.id;list.append(b)}if(!list.children.length){tab('cast');toast('Use Add beside a cast character to place it in this scene.');return}$('chooseCharacterDialog').showModal()};$('closeChooseCharacter').onclick=()=>$('chooseCharacterDialog').close();
$('selectionUnlock').onclick=()=>{for(const o of selectedLayers())o.locked=false;const c=tracks().find(c=>c.id===selectedAudio);if(c)c.locked=false;save();render()};
for(const button of characterWorkspace.querySelectorAll('button'))button.onclick=()=>{const mode=button.dataset.characterSection;if(mode==='add'){tab('cast');$('easyAnimationLibrary').hidden=true;document.querySelector('.library').scrollTop=0;toast('Choose Add beside a character, create one, or rig a picture.');return}characterWorkspaceTab=mode;showCharacterSection()};
function showCharacterSection(){for(const b of characterWorkspace.querySelectorAll('button')){const active=b.dataset.characterSection===characterWorkspaceTab;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))}for(const panel of $('controls').querySelectorAll('[data-character-panel]'))panel.hidden=panel.dataset.characterPanel!==characterWorkspaceTab}
function characterControlSection(el){const text=el.querySelector('summary')?.textContent||'';if(/Voice|mouth|Mouth|lip-sync/.test(text)||el.id==='characterVoiceWorkflow')return'voice';if(/Face performance|Hand shapes|feather|Cut-out/.test(text))return'appearance';return'animate'}
function organizeCharacterControls(o){if(!isAnimatedCharacter(o))return;const controls=$('controls'),advanced=$('advancedInspectorControls');if(advanced){for(const el of [...advanced.children])if(el.tagName!=='SUMMARY')advanced.before(el);advanced.remove()}const panels={};for(const id of ['appearance','animate','voice']){const panel=document.createElement('section');panel.dataset.characterPanel=id;panel.className='character-panel';panels[id]=panel}const advancedAnimation=document.createElement('details');advancedAnimation.id='advancedInspectorControls';advancedAnimation.innerHTML='<summary>More animation controls</summary>';advancedAnimation.open=inspectorAdvancedOpen;for(const el of [...controls.children]){let section=characterControlSection(el);if(el.tagName==='LABEL'||el.id==='deleteKey')section='appearance';if(el.tagName==='DETAILS'&&section==='animate'&&!['Easy animation'].includes(el.querySelector('summary')?.textContent))advancedAnimation.append(el);else panels[section].append(el)}if(advancedAnimation.children.length>1)panels.animate.append(advancedAnimation);advancedAnimation.addEventListener('toggle',()=>{inspectorAdvancedOpen=advancedAnimation.open});const edit=storyButton(o.type==='puppet'?'Edit picture rig & appearance':'Edit character appearance',()=>o.type==='puppet'?openImageRig(o):openCreator(o.character));edit.id='editSelectedCharacterAppearance';edit.disabled=!!o.locked;panels.appearance.prepend(edit);controls.append(panels.appearance,panels.animate,panels.voice);showCharacterSection()}
function selectionStatus(){const o=object(),c=tracks().find(c=>c.id===selectedAudio),list=selectedLayers(),actor=isAnimatedCharacter(o),locked=list.some(o=>o.locked)||!!c?.locked,kind=list.length>1?list.length+' layers':actor?'Character':o?({text:'Text',image:'Image',video:'Video',shape:'Shape',flipbook:'Drawing'}[o.type]||'Object'):c?'Audio':'Nothing';$('selectionKind').textContent=kind+' selected';$('selectionExplanation').textContent=locked?'Editing lock is on. Unlock here to make changes.':actor?'Edit appearance, movement or voice below.':o?'Character actions need a character selected.':c?'Audio timing and volume appear below the timeline.':'Click a layer or choose a character to start.';$('selectionUnlock').hidden=!locked;$('selectionChoose').hidden=actor||!current().objects.some(isAnimatedCharacter);characterWorkspace.hidden=!actor;selectionNotice.classList.toggle('editing-locked',locked);for(const id of ['openEasyAnimation','libraryBodyAnimation','libraryMotionClips'])if($(id))$(id).title=actor?'Animate '+o.name:'Select a character; a sole scene character is selected automatically.';for(const button of document.querySelectorAll('.track-label button[title="Lock / unlock layer"]')){const isLocked=button.textContent.includes('🔒');button.setAttribute('aria-label',isLocked?'Unlock layer':'Lock layer');button.title=isLocked?'Unlock layer editing':'Lock layer editing';button.textContent=isLocked?'🔒':'Lock'}positionSelectionToolbar()}
const floatingSelection=document.createElement('div');floatingSelection.id='canvasSelectionToolbar';floatingSelection.className='canvas-selection-toolbar';floatingSelection.innerHTML='<button id="canvasEdit">Edit</button><button id="canvasVoice">Voice</button><button id="canvasDuplicate">Duplicate</button><button id="canvasLock">Lock</button>';
document.querySelector('.paperstage').append(floatingSelection);
$('canvasEdit').onclick=()=>{const o=object();if(!o)return;if(o.locked){$('selectionUnlock').click();return}if(o.type==='text')$('editTextOnCanvas')?.click();else if(isAnimatedCharacter(o)){characterWorkspaceTab='animate';showCharacterSection();setCanvasMode('pose')}else if(o.motionPath)beginPathEditing('layer');else toast('Drag the corner handles to resize. Drag the gold handle to rotate.')};
$('canvasVoice').onclick=()=>{characterWorkspaceTab='voice';showCharacterSection()};$('canvasDuplicate').onclick=()=>$('duplicate').click();$('canvasLock').onclick=()=>$('lockLayer').click();
function positionSelectionToolbar(){const o=object(),box=selectionBounds(),paper=document.querySelector('.paperstage'),stageRect=$('stage').getBoundingClientRect(),paperRect=paper.getBoundingClientRect();floatingSelection.hidden=!o||!box||playing||recording||!!canvasInteraction||!!pathEditor||canvasMode!=='select';if(floatingSelection.hidden)return;const cam=cameraAt(current(),time),x=stageRect.left-paperRect.left+(480+(box.cx-cam.x)*cam.zoom)/960*stageRect.width,y=stageRect.top-paperRect.top+(270+(box.y-cam.y)*cam.zoom)/540*stageRect.height;floatingSelection.style.left=clamp(x-floatingSelection.offsetWidth/2,8,Math.max(8,paper.clientWidth-floatingSelection.offsetWidth-8))+'px';floatingSelection.style.top=clamp(y-48,6,Math.max(6,paper.clientHeight-38))+'px';$('canvasVoice').hidden=!isAnimatedCharacter(o);$('canvasEdit').textContent=o.locked?'Unlock':o.type==='text'?'Edit text':isAnimatedCharacter(o)?'Pose':'Edit';$('canvasDuplicate').disabled=!!o.locked;$('canvasLock').textContent=o.locked?'Unlock':'Lock'}
const renderControlsBeforeWorkflow=renderControls;renderControls=function(){renderControlsBeforeWorkflow();organizeCharacterControls(object());selectionStatus()};
const extrasBeforeWorkflow=renderExtras;renderExtras=function(){extrasBeforeWorkflow();selectionStatus()};
const drawBeforeSelectionToolbar=draw;draw=function(){drawBeforeSelectionToolbar();positionSelectionToolbar()};
new ResizeObserver(positionSelectionToolbar).observe(document.querySelector('.paperstage'));
// Missing selection and an explicit editing lock are different states throughout the app.
const toastBeforeSelection=toast;toast=function(message){if(/Select an unlocked character(?: or picture rig)?\.?|Choose an unlocked character\.?/.test(message)){const o=object();message=isAnimatedCharacter(o)&&o.locked?o.name+' has an editing lock. Choose Unlock editing in the inspector.':'Select a character on the canvas first. This is not an editing lock.'}toastBeforeSelection(message)};
